var authGuard = (route, state) => {
  const authService = inject(AuthService);
  const router = inject(Router);
  return authService.authChecked$.pipe(filter((checked) => checked), take(1), switchMap(() => authService.isLoggedIn$), take(1), map((isLoggedIn) => {
    if (isLoggedIn)
      return true;
    router.navigate(["/login"], { queryParams: { returnUrl: state.url } });
    return false;
  }));
};

// src/app/guards/admin.guard.ts
var adminGuard = (route, state) => {
  const authService = inject(AuthService);
  const router = inject(Router);
  return authService.authChecked$.pipe(filter((checked) => checked), take(1), switchMap(() => authService.currentUser$), take(1), map((user) => {
    if (user && user.roles?.includes("ROLE_ADMIN"))
      return true;
    router.navigate(["/home"]);
    return false;
  }));
};

// src/app/guards/full-access.guard.ts
var fullAccessGuard = (route, state) => {
  const authService = inject(AuthService);
  const router = inject(Router);
  return authService.authChecked$.pipe(filter((checked) => checked), take(1), switchMap(() => authService.currentUser$), take(1), map((user) => {
    if (user && user.accessLevel === "FULL")
      return true;
    router.navigate(["/home"]);
    return false;
  }));
};

