  addNewAttachments(ids, permitType) {
    const currentPackage = this.selectedDailyPermitPackageSubject.value;
    if (!currentPackage) {
      console.error("No package selected.");
      return;
    }
    switch (permitType) {
      case "workRequests":
        currentPackage.workRequestIds = [...currentPackage.workRequests.map((r) => r.id), ...ids];
        break;
      case "safeWorks":
        currentPackage.safeWorkIds = [...currentPackage.safeWorks.map((r) => r.id), ...ids];
        break;
      case "hotWorks":
        currentPackage.hotWorkIds = [...currentPackage.hotWorks.map((r) => r.id), ...ids];
        break;
      case "confinedSpaces":
        currentPackage.confinedSpaceIds = [...currentPackage.confinedSpaces.map((r) => r.id), ...ids];
        break;
      case "lotos":
        currentPackage.lotoIds = [...currentPackage.lotos.map((l2) => l2.id), ...ids];
        break;
      case "energizedWorkPermits":
        currentPackage.energizedWorkPermitIds = [...currentPackage.energizedWorkPermits.map((p2) => p2.id), ...ids];
        break;
      case "excavationPermits":
        currentPackage.excavationPermitIds = [...currentPackage.excavationPermits.map((p2) => p2.id), ...ids];
        break;
      case "ventingPermits":
        currentPackage.ventingPermitIds = [...currentPackage.ventingPermits.map((p2) => p2.id), ...ids];
        break;
      default:
        console.error("Invalid permit type:", permitType);
        return;
    }
    this.dailyPermitPackageService.createDailyPermitPackage(currentPackage).pipe(takeUntilDestroyed(this.destroyRef)).subscribe({
      next: (response) => {
        const updatedPackage = new DailyPermitPackageDto(response.responseData);
        this.updateDailyPermitPackageInList(updatedPackage);
        this.setSelectedPackage(updatedPackage);
      },
      error: (err) => {
        console.error("Failed to add work request to package:", err);
      }
    });
  }
