  removePermitFromPackageItem(item, permitType) {
    const id2 = item?.id;
    if (typeof id2 === "number" && !Number.isNaN(id2)) {
      this.removePermitFromPackage(id2, permitType);
      return;
    }
    const currentPackage = this.selectedDailyPermitPackageSubject.value;
    if (!currentPackage) {
      console.error("No package selected.");
      return;
    }
    const updatedPackage = new DailyPermitPackageDto(currentPackage);
    switch (permitType) {
      case "workRequests":
        updatedPackage.workRequests = updatedPackage.workRequests.filter((entry) => entry !== item);
        updatedPackage.workRequestIds = updatedPackage.workRequests.map((entry) => entry.id).filter((entryId) => typeof entryId === "number");
        break;
      case "safeWorks":
        updatedPackage.safeWorks = updatedPackage.safeWorks.filter((entry) => entry !== item);
        updatedPackage.safeWorkIds = updatedPackage.safeWorks.map((entry) => entry.id).filter((entryId) => typeof entryId === "number");
        break;
      case "hotWorks":
        updatedPackage.hotWorks = updatedPackage.hotWorks.filter((entry) => entry !== item);
        updatedPackage.hotWorkIds = updatedPackage.hotWorks.map((entry) => entry.id).filter((entryId) => typeof entryId === "number");
        break;
      case "confinedSpaces":
        updatedPackage.confinedSpaces = updatedPackage.confinedSpaces.filter((entry) => entry !== item);
        updatedPackage.confinedSpaceIds = updatedPackage.confinedSpaces.map((entry) => entry.id).filter((entryId) => typeof entryId === "number");
        break;
      case "lotos":
        updatedPackage.lotos = updatedPackage.lotos.filter((entry) => entry !== item);
        updatedPackage.lotoIds = updatedPackage.lotos.map((entry) => entry.id).filter((entryId) => typeof entryId === "number");
        break;
      case "energizedWorkPermits":
        updatedPackage.energizedWorkPermits = updatedPackage.energizedWorkPermits.filter((entry) => entry !== item);
        updatedPackage.energizedWorkPermitIds = updatedPackage.energizedWorkPermits.map((entry) => entry.id).filter((entryId) => typeof entryId === "number");
        break;
      case "excavationPermits":
        updatedPackage.excavationPermits = updatedPackage.excavationPermits.filter((entry) => entry !== item);
        updatedPackage.excavationPermitIds = updatedPackage.excavationPermits.map((entry) => entry.id).filter((entryId) => typeof entryId === "number");
        break;
      case "ventingPermits":
        updatedPackage.ventingPermits = updatedPackage.ventingPermits.filter((entry) => entry !== item);
        updatedPackage.ventingPermitIds = updatedPackage.ventingPermits.map((entry) => entry.id).filter((entryId) => typeof entryId === "number");
        break;
      default:
        console.error("Invalid permit type:", permitType);
        return;
    }
    this.updateDailyPermitPackageInList(updatedPackage);
    this.setSelectedPackage(updatedPackage);
  }
